"""Launch Planner Agent: Generates 30-day actionable roadmap (PRD §36.14, F-008, F-009)."""

import logging

from pydantic import BaseModel, Field

from app.agents.config import agent_config
from app.agents.llm import get_model

logger = logging.getLogger(__name__)


class PlannerAgentTask(BaseModel):
    """Single actionable task item generated by Launch Planner."""

    title: str = Field(..., description="Specific, actionable task title")
    description: str = Field(..., description="Step-by-step guidance on how to accomplish the task")
    week: int = Field(..., ge=1, le=4, description="Plan week 1 to 4")
    category: str = Field(..., description="Category: setup, content, outreach, or operations")
    day_offset: int = Field(..., ge=1, le=30, description="Day 1 to 30 of the launch roadmap")


class PlannerAgentOutput(BaseModel):
    """30-day launch roadmap output."""

    summary: str
    tasks: list[PlannerAgentTask]


def _rule_based_fallback_plan(
    business_name: str,
    niche: str,
    city: str,
    area: str | None = None,
    platforms: list[str] | None = None,
) -> PlannerAgentOutput:
    """Deterministic, high-quality 30-day launch plan tailored to Pakistani micro-businesses."""
    loc = f"{area}, {city}" if area else city
    plats = platforms or ["WhatsApp", "Instagram"]
    primary_plat = plats[0] if plats else "WhatsApp"

    tasks = [
        # --- Week 1: Setup & Foundation (Days 1-7) ---
        PlannerAgentTask(
            title=f"Set up branded {primary_plat} profile with business catalog",
            description=f"Configure business name '{business_name}', operating hours, address in {loc}, and upload primary offerings with pricing into the product catalog.",
            week=1,
            category="setup",
            day_offset=1,
        ),
        PlannerAgentTask(
            title="Create and configure social media business pages",
            description="Establish consistent handles, profile picture with clear logo/name, and a bio stating your unique specialty and delivery zone.",
            week=1,
            category="setup",
            day_offset=2,
        ),
        PlannerAgentTask(
            title="Source packaging materials and wholesale stock",
            description=f"Purchase 30-50 units of food-safe boxes, customized sticker labels, and packaging tape from local wholesale suppliers in {city}.",
            week=1,
            category="operations",
            day_offset=3,
        ),
        PlannerAgentTask(
            title="Finalize recipe/production batch sizing and unit costs",
            description="Standardize portion sizes and verify that raw ingredient usage matches the cost sheet to ensure a minimum 35% margin.",
            week=1,
            category="operations",
            day_offset=4,
        ),
        PlannerAgentTask(
            title="Photograph sample offerings in natural morning light",
            description="Take 10-15 clean smartphone photos with neutral background, showing close-up textures and packaged presentation.",
            week=1,
            category="content",
            day_offset=5,
        ),
        PlannerAgentTask(
            title="Soft announcement to friends & family on personal channels",
            description="Share a personal teaser story on your status asking close contacts to save the business contact number and share feedback.",
            week=1,
            category="outreach",
            day_offset=7,
        ),

        # --- Week 2: First Sales & Early Outreach (Days 8-14) ---
        PlannerAgentTask(
            title="Publish official launch post and behind-the-scenes reel",
            description="Show the handmade preparation process and announce that orders are officially open for delivery across your territory.",
            week=2,
            category="content",
            day_offset=8,
        ),
        PlannerAgentTask(
            title="Launch an introductory neighborhood promotional offer",
            description="Offer 10% discount on first orders or complimentary sample bites to incentivize initial hesitant buyers.",
            week=2,
            category="outreach",
            day_offset=9,
        ),
        PlannerAgentTask(
            title="Direct personalized WhatsApp outreach to 20 local contacts",
            description="Send a polite, personal greeting with your digital product menu card and invite them to place a trial order.",
            week=2,
            category="outreach",
            day_offset=10,
        ),
        PlannerAgentTask(
            title="Deliver first 3 customer orders and verify on-time delivery",
            description="Include a handwritten thank-you card in each order package and confirm safe arrival with the customer within 2 hours.",
            week=2,
            category="operations",
            day_offset=12,
        ),
        PlannerAgentTask(
            title="Request photo reviews and WhatsApp feedback",
            description="Politely request satisfied customers to send a quick photo of their experience to share on social proof highlights.",
            week=2,
            category="outreach",
            day_offset=13,
        ),
        PlannerAgentTask(
            title="Replenish raw supplies based on first-week sales velocity",
            description="Re-order the highest-demand ingredients before weekend rush to avoid running out of stock mid-shift.",
            week=2,
            category="operations",
            day_offset=14,
        ),

        # --- Week 3: Traction & Neighborhood Social Proof (Days 15-21) ---
        PlannerAgentTask(
            title="Share customer testimonial screenshots on stories and status",
            description="Curate positive reviews and highlight praise for taste, presentation, and quick response times.",
            week=3,
            category="content",
            day_offset=15,
        ),
        PlannerAgentTask(
            title=f"Partner with local residential or apartment society groups in {loc}",
            description="Share a weekly menu bulletin in neighborhood resident groups with permission from the group admin.",
            week=3,
            category="outreach",
            day_offset=16,
        ),
        PlannerAgentTask(
            title="Introduce a limited-quantity weekend bundle special",
            description="Bundle two complementary items at a slight discount to increase average order value from Rs. 800 to Rs. 1,500.",
            week=3,
            category="content",
            day_offset=18,
        ),
        PlannerAgentTask(
            title="Perform mid-month revenue and cash-flow check",
            description="Calculate total collected cash vs. wholesale expenses and ensure weekly profit goals are being met.",
            week=3,
            category="operations",
            day_offset=19,
        ),
        PlannerAgentTask(
            title="Follow up with week 1 & 2 customers for repeat weekend orders",
            description="Send a polite reminder: 'Planning your weekend treats? We are taking advance slots until Thursday night.'",
            week=3,
            category="outreach",
            day_offset=20,
        ),
        PlannerAgentTask(
            title="Post educational content answering common buyer questions",
            description="Explain ingredients, shelf-life, storage tips, or dietary customization options to build buyer trust.",
            week=3,
            category="content",
            day_offset=21,
        ),

        # --- Week 4: Operational Rhythm & Growth (Days 22-30) ---
        PlannerAgentTask(
            title="Establish recurring weekly batch production calendar",
            description="Standardize grocery shopping on Mondays, batch prep on Wednesdays/Fridays to keep work under 20-25 hours/week.",
            week=4,
            category="operations",
            day_offset=23,
        ),
        PlannerAgentTask(
            title="Analyze best-selling offerings and prune low-margin items",
            description="Focus marketing efforts on the 2 top revenue-driving products and discontinue items that take excessive prep time.",
            week=4,
            category="operations",
            day_offset=25,
        ),
        PlannerAgentTask(
            title="Run month-end customer appreciation shoutout",
            description="Thank all month-1 patrons publicly and announce upcoming new seasonal specials for next month.",
            week=4,
            category="content",
            day_offset=27,
        ),
        PlannerAgentTask(
            title="Set up advance booking calendar for following month",
            description="Invite customers to reserve dates in advance for birthdays, parties, or family gatherings.",
            week=4,
            category="outreach",
            day_offset=28,
        ),
        PlannerAgentTask(
            title="Document lessons learned and supplier vendor contracts",
            description="Record reliable riders/couriers, trusted packaging vendors, and update cost inputs for price adjustments.",
            week=4,
            category="operations",
            day_offset=29,
        ),
        PlannerAgentTask(
            title="Review month-1 milestone achievements vs. initial budget",
            description=f"Compare actual net earnings against your startup capital to plan reinvestment into {business_name} scaling.",
            week=4,
            category="operations",
            day_offset=30,
        ),
    ]

    summary = (
        f"A customized 30-day launch roadmap for {business_name} in {loc}. "
        "Week 1 establishes foundational profiles and packaging; Week 2 captures your first paying customers; "
        "Week 3 drives community social proof and repeat orders; Week 4 solidifies a sustainable operational routine."
    )
    return PlannerAgentOutput(summary=summary, tasks=tasks)


async def run_planner_agent(
    business_name: str,
    niche: str,
    city: str,
    area: str | None = None,
    budget_pkr: int = 20000,
    hours_per_week: int = 20,
    platforms: list[str] | None = None,
    target_customer: str | None = None,
    products_summary: str = "",
) -> PlannerAgentOutput:
    """Run Launch Planner Agent to construct a 30-day roadmap with dated actionable tasks (PRD §36.14)."""
    # Deterministic fallback check for test keys or missing API key
    is_mock_key = agent_config.api_key in ("missing-key-for-test", "test-key-not-for-live")
    if not agent_config.api_key or is_mock_key:
        return _rule_based_fallback_plan(
            business_name=business_name,
            niche=niche,
            city=city,
            area=area,
            platforms=platforms,
        )

    fallback = _rule_based_fallback_plan(
        business_name=business_name,
        niche=niche,
        city=city,
        area=area,
        platforms=platforms,
    )

    try:
        from agents import Agent, Runner

        prompt = (
            f"Business: '{business_name}' ({niche}) in {area or ''}, {city}.\n"
            f"Budget: PKR {budget_pkr:,}, Weekly Availability: {hours_per_week} hours.\n"
            f"Target Customer: {target_customer or 'Local neighborhood & online buyers'}.\n"
            f"Platforms: {', '.join(platforms or ['WhatsApp', 'Instagram'])}.\n"
            f"Products: {products_summary or 'Core items'}.\n\n"
            "Generate a 30-day launch plan with 5-8 actionable tasks per week across 4 weeks (total 20-28 tasks). "
            "Week 1: Setup & foundation. Week 2: First sales & outreach. Weeks 3-4: Growth & operations. "
            "Tasks MUST be specific and culturally grounded in Pakistani home entrepreneurship."
        )

        agent = Agent(
            name="launch_planner",
            model=get_model(agent_config.gemini_model_name),
            instructions=(
                "You are Hunar's Launch Planner Agent. Generate a concrete 30-day plan. "
                "Tasks must be specific ('Create WhatsApp Catalog with prices' not 'Setup channels')."
            ),
            output_type=PlannerAgentOutput,
        )

        result = await Runner.run(agent, prompt)
        if isinstance(result.final_output, PlannerAgentOutput) and len(result.final_output.tasks) >= 12:
            return result.final_output
        return fallback
    except Exception as exc:
        logger.warning("Launch Planner LLM call failed, returning deterministic curriculum: %s", exc)
        return fallback
